class TestLockFreeRingBuffer:
    """Core invariant testing for the ring buffer."""

    # --- Initialization ---

    def test_initialization(self, ring_buffer):
        assert ring_buffer.capacity == 1024
        assert ring_buffer.write_index == 0
        assert ring_buffer.read_index == 0

    def test_mmap_allocated_size(self, ring_buffer):
        """INV-001: Buffer must be pre-allocated to capacity * 80 bytes."""
        assert ring_buffer.buffer.size() == 1024 * 80

    def test_invalid_capacity(self):
        with pytest.raises((ValueError, OverflowError)):
            LockFreeRingBuffer(capacity=0)
        with pytest.raises((ValueError, OverflowError)):
            LockFreeRingBuffer(capacity=-1)

    # --- Basic write/read operations ---

    def test_write_and_read_single_packet(self, ring_buffer, sample_packet):
        """Basic roundtrip."""
        assert ring_buffer.write(sample_packet) is True
        packet = ring_buffer.read()
        assert packet == sample_packet

    def test_write_returns_false_when_full(self, small_ring_buffer, sample_packet):
        """INV-001: Write must fail gracefully when buffer full."""
        for _ in range(small_ring_buffer.capacity):
            assert small_ring_buffer.write(sample_packet) is True
        # Buffer is now full
        assert small_ring_buffer.write(sample_packet) is False

    def test_read_returns_none_when_empty(self, ring_buffer):
        """Read from empty buffer returns None."""
        assert ring_buffer.read() is None

    def test_fifo_order(self, ring_buffer):
        """INV-002: FIFO ordering must be preserved."""
        packets = [
            TelemetryPacket(
                timestamp=i,
                sensor_id=i,
                telemetry_type=1,
                payload=bytes([i] * 64),
            )
            for i in range(10)
        ]
        for p in packets:
            ring_buffer.write(p)

        for expected in packets:
            assert ring_buffer.read() == expected

    # --- Wrap-around behavior ---

    def test_wrap_around(self, small_ring_buffer, sample_packet):
        """Buffer must handle index wrap-around correctly."""
        for _ in range(small_ring_buffer.capacity):
            small_ring_buffer.write(sample_packet)
        for _ in range(small_ring_buffer.capacity):
            assert small_ring_buffer.read() == sample_packet

        # Now write again after wrap
        assert small_ring_buffer.write(sample_packet) is True
        assert small_ring_buffer.read() == sample_packet

    # --- Concurrency safety (INV-002, INV-003) ---

    @pytest.mark.asyncio
    async def test_concurrent_writer_reader(self, ring_buffer):
        """Stress test: concurrent writes/reads must not corrupt data."""
        num_packets = 1000
        write_task = asyncio.create_task(self._async_writer(ring_buffer, num_packets))
        read_task = asyncio.create_task(self._async_reader(ring_buffer, num_packets))
        await asyncio.gather(write_task, read_task)

    async def _async_writer(self, buffer, count):
        for i in range(count):
            packet = TelemetryPacket(
                timestamp=i,
                sensor_id=i,
                telemetry_type=1,
                payload=bytes([i % 256] * 64),
            )
            while not buffer.write(packet):
                await asyncio.sleep(0)

    async def _async_reader(self, buffer, count):
        received = []
        while len(received) < count:
            packet = buffer.read()
            if packet is not None:
                received.append(packet)
            else:
                await asyncio.sleep(0)
        assert len(received) == count

    # --- Memory safety (INV-001) ---

    def test_no_buffer_overflow(self, ring_buffer, sample_packet):
        """Writing beyond capacity must not corrupt memory."""
        for _ in range(ring_buffer.capacity):
            ring_buffer.write(sample_packet)
        # Attempt overflow
        assert ring_buffer.write(sample_packet) is False
        # Buffer content still valid
        for _ in range(ring_buffer.capacity):
            assert ring_buffer.read() == sample_packet

    # --- Property-based tests ---

    @pytest.mark.parametrize("capacity", [1, 2, 8, 64, 1024])
    def test_property_ring_buffer_roundtrip(self, capacity):
        """Property: write-then-read preserves packet integrity."""
        buffer = LockFreeRingBuffer(capacity=capacity)
        for i in range(capacity):
            packet = TelemetryPacket(
                timestamp=i,
                sensor_id=i,
                telemetry_type=1,
                payload=bytes([i % 256] * 64),
            )
            assert buffer.write(packet) is True
        for i in range(capacity):
            packet = buffer.read()
            assert packet is not None
            assert packet.timestamp == i
            assert packet.sensor_id == i

    @pytest.mark.parametrize("operations", [10, 100, 1000])
    def test_property_random_operations(self, operations):
        """Property: random interleaved writes/reads maintain consistency."""
        import random
        random.seed(42)
        buffer = LockFreeRingBuffer(capacity=16)
        expected_queue = deque()

        for _ in range(operations):
            if random.random() < 0.6:  # 60% write
                packet = TelemetryPacket(
                    timestamp=random.randint(0, 1_000_000),
                    sensor_id=random.randint(0, 100),
                    telemetry_type=1,
                    payload=bytes(random.getrandbits(8) for _ in range(64)),
                )
                if len(expected_queue) < buffer.capacity:
                    assert buffer.write(packet) is True
                    expected_queue.append(packet)
                else:
                    assert buffer.write(packet) is False
            else:  # 40% read
                actual = buffer.read()
                if expected_queue:
                    expected = expected_queue.popleft()
                    assert actual == expected
                else:
                    assert actual is None

    # --- Cleanup ---

    def test_buffer_close(self, ring_buffer):
        """Buffer must be closable and release mmap."""
