class TestPerformance:
    """High-throughput validation for production readiness."""

    def test_high_throughput_roundtrip(self):
        """100k packets through 64k ring buffer."""
        buffer = LockFreeRingBuffer(capacity=65536)
        num_packets = 100_000

        # Write phase
        for i in range(num_packets):
            packet = TelemetryPacket(
                timestamp=i,
                sensor_id=i % 1000,
                telemetry_type=1,
                payload=bytes([i % 256] * 64),
            )
            buffer.write(packet)

        # Read phase
        count = 0
        while True:
            packet = buffer.read()
            if packet is None:
                break
            count += 1
        assert count == num_packets

    def test_memory_footprint(self):
        """Verify mmap allocation is efficient."""
        buffer = LockFreeRingBuffer(capacity=65536)
        # 65536 * 80 = 5,242,880 bytes ≈ 5 MB
        assert buffer.buffer.size() == 5_242_880


